/* ===== Explicação dos exames em linguagem simples (30/10, anotações 64, 71 e 72): para que serve e como se prepara.
   Vem do cadastro do exame (Cadastros › Exames › "?") e pode ser importada de planilha ou banco em Importar e exportar. ===== */
const EX_INFO={
 GLI:['Mede o açúcar no sangue. Ajuda a investigar e acompanhar diabetes e hipoglicemia.','Jejum de 8 a 12 horas. Água pode.'],
 COL:['Mede as gorduras do sangue (colesterol total, HDL, LDL e triglicerídeos). Avalia o risco de doenças do coração.','Jejum de 12 horas; evite álcool na véspera.'],
 TGO:['Enzima do fígado e dos músculos. Alta pode indicar sofrimento do fígado.','Sem preparo especial.'],
 TGP:['Enzima do fígado. Alta sugere inflamação ou lesão do fígado.','Sem preparo especial.'],
 HEMO:['Conta as células do sangue: glóbulos vermelhos, brancos e plaquetas. Avalia anemia, infecções e coagulação.','Sem jejum obrigatório.'],
 K:['Mede o potássio, essencial para coração e músculos. Muito alto ou muito baixo é urgente.','Sem preparo; evite abrir e fechar a mão durante a coleta.'],
 CREA:['Avalia o funcionamento dos rins.','Sem preparo especial.'],
 UREIA:['Avalia os rins e a hidratação.','Sem preparo especial.'],
 HBA1C:['Mostra a média do açúcar no sangue dos últimos 3 meses. Acompanha o diabetes.','Não precisa de jejum.'],
 TSH:['Hormônio que controla a tireoide. Investiga hipo e hipertireoidismo.','Sem jejum; colha de manhã se possível.'],
 T4L:['Hormônio da tireoide em forma livre. Complementa o TSH.','Sem preparo especial.'],
 VITD:['Vitamina dos ossos e da imunidade.','Sem preparo especial.'],
 EAS:['Exame de urina de rotina: infecção, sangue, proteína e açúcar na urina.','Primeira urina da manhã, jato médio, após higiene.'],
 PSA:['Marcador da próstata. Acompanha e investiga alterações da próstata.','48 h sem relação sexual, bicicleta ou toque retal.'],
 FERR:['Mede a reserva de ferro do corpo. Investiga anemia e excesso de ferro.','Jejum de 4 horas.'],
 TRIG:['Gordura do sangue ligada à alimentação e ao risco cardíaco.','Jejum de 12 horas; sem álcool na véspera.'],
 BHCG:['Hormônio da gravidez. Confirma e acompanha a gestação.','Sem preparo especial.'],
};
const exInfoDe=c=>EX_INFO[c]||['Explicação em linguagem simples ainda não cadastrada para este exame.','Veja o preparo com a recepção.'];
/* "?" ao lado do nome do exame: mostra para que serve e as orientações de coleta ao passar o mouse (e ao focar). */
function exameTip(c,nome){const [serve,coleta]=exInfoDe(c);return `<span class="ti-line"><span class="ti-txt" title="${esc(nome||(EX[c]?EX[c].n:c))}">${esc(nome||(EX[c]?EX[c].n:c))}</span><span class="tipicon qmark" tabindex="0" role="note" aria-label="Para que serve: ${serve.replace(/"/g,'')} Preparo: ${coleta.replace(/"/g,'')}">?<span class="tip"><b>Para que serve:</b> ${serve}<br><b>Preparo e coleta:</b> ${coleta}</span></span></span>`}
/* Histórico de um exame do laudo: só o último resultado aparece na tabela; clicar abre tudo, com gráfico e fora da referência em vermelho (anotação 62). */
const LD_HIST={GLI:[['14/10','240'],['02/08','218'],['12/03','255'],['18/12/25','231']],COL:[['14/10','198'],['02/08','184'],['12/03','176']],TGO:[['14/10','31']],HBA1C:[['10/07','5,9'],['12/01','5,7']]};
function ldHistCell(c,atual){const h=LD_HIST[c]||[];if(!h.length)return '<span class="tl">primeiro resultado</span>';const f=FAIXA[c];const [d,v]=h[0];const fora=f&&(numRes(v)<f[0]||numRes(v)>f[1]);return `<button type="button" class="hist-ult ${fora?'fora':''}" onclick="event.stopPropagation();ldHist('${c}','${atual.replace(/'/g,'')}')" ${tipAttr('Histórico','Último resultado anterior. Clique para ver todos, com gráfico; fora da referência fica em vermelho.')}>${d} · <b>${v}</b>${h.length>1?` <small>+${h.length-1}</small>`:''}</button>`}
function ldHist(c,atual){const h=LD_HIST[c]||[];const f=FAIXA[c];const n=EX[c]?EX[c].n:c;const ref=f?(f[0]?`${String(f[0]).replace('.',',')} a ${String(f[1]).replace('.',',')}`:'até '+f[1])+' '+f[2]:'—';
 openModal(`${mh('Histórico · '+n+' · Maria Helena Souza')}<div class="mb">${graficoHist(h,f,numRes(atual))}${tabela(['Data','Resultado','Referência',''],[['hoje',atual,ref,true]].concat(h.map(([d,v])=>[d,v+(f?' '+f[2]:''),ref,false])).map(([d,v,r,hoje])=>{const fora=f&&(numRes(v)<f[0]||numRes(v)>f[1]);return `<tr>${td('Data',hoje?'<b>hoje</b>':d)}${td('Resultado',`<b class="${fora?'fora':''}">${v}</b>${f?setaHtml(dirFaixa(numRes(v),f[0],f[1])):''}${fora?' <span class="badge err">fora da referência</span>':''}`)}${td('Referência',r)}${td('',hoje?'<span class="badge info">este laudo</span>':`<button class="btn sm ghost" onclick="toast('Laudo de ${d} aberto')">Ver laudo</button>`)}</tr>`}))}<p class="tl" style="margin-top:8px">Só resultados deste laboratório. ${exameTip(c,'Sobre o exame')}</p></div><div class="mf"><button class="btn" onclick="closeModal()">Fechar</button></div>`,'wide')}

