function lpSug(q){const b=$('#lpSug');if(!b)return;const s=semAc((q||'').replace(/\s·.*/,''));const l=LAUDOS.filter(x=>!s||semAc(x.prot+' '+x.pac).includes(s));b.innerHTML=l.length?l.map(x=>`<button type="button" onclick="lpAbrir('${x.prot}')"><b>${x.prot} · ${esc(x.pac)}</b><small>${x.dr} · ${x.h} · ${x.sit}${x.marca?' · '+x.marca:''}</small></button>`).join(''):'<p class="tl" style="padding:8px 10px">Nenhum laudo com esse protocolo ou nome.</p>';b.classList.add('show')}
document.addEventListener('pointerdown',e=>{const b=document.getElementById('lpSug');if(b&&b.classList.contains('show')&&!e.target.closest('#lpSug,#lpQ'))b.classList.remove('show')},true);
