function enBusca(q){q=semAc(q||'');const d=q.replace(/\D/g,'');return EN_PACS.filter(p=>q.length>=3&&(semAc(p.n).includes(q)||(d.length>=3&&p.cpf.replace(/\D/g,'').includes(d))))}
function enRetirada(prot){EN_SEL=prot?EN_PACS.find(p=>p.prot===prot)||null:null;EN_QUEM='paciente';EN_VER='pb';enRender()}
function enRender(q){const p=EN_SEL;const res=enBusca(q);
 openModal(`${mh('Entrega no balcão')}<div class="mb">
 <div class="field"><label>Paciente ${info('Digite o CPF ou o nome: a lista mostra a data de nascimento ao lado para confirmar sem risco de troca.')}</label><div class="inwrap">${LUPA}<input class="in" id="enQ" placeholder="CPF ou nome do paciente" value="${esc(q||(p?p.n:''))}" autocomplete="off" oninput="enRender(this.value)"></div></div>
 ${!p&&q&&q.length>=3?(res.length?`<div class="at-list" style="margin-bottom:10px">${res.map(r=>`<div class="at-row clk" onclick="EN_SEL=EN_PACS.find(x=>x.prot==='${r.prot}');enRender()"><div class="grow"><b>${esc(r.n)}</b> <span class="badge neutral">nasc. ${r.dn}</span><small>CPF ${r.cpf.slice(0,3)}.***.***-${r.cpf.slice(-2)} · laudo <span class="mono">${r.prot}</span> · ${r.sit}</small></div><button class="btn sm sec">Selecionar</button></div>`).join('')}</div>`:'<p class="tl" style="margin-bottom:10px">Ninguém com esse nome ou CPF. Confira a digitação.</p>'):''}
 ${p?`<div class="at-found"><h4>${esc(p.n)} <span class="badge neutral">nasc. ${p.dn}</span> ${p.sens?'<span class="badge err">resultado sensível</span>':''}</h4><div>Laudo <span class="mono">${p.prot}</span> · ${p.sit}</div></div>
 <div class="alert info" style="margin:10px 0"><span><b>O que o paciente autorizou no atendimento</b> ${info('Premissas colhidas no atendimento (obrigatório, configurável): canais, PDF, terceiros nomeados e como autorizou. A entrega só segue dentro delas.')}<br>Canais: ${p.canais} · PDF por mensagem: ${p.pdf?'autorizado':'não autorizado'} · Terceiros: ${p.terc.length?p.terc.map(t=>'<b>'+t[0]+'</b> ('+t[1]+')').join(', '):'nenhum'}<br><small class="tl">Como autorizou: ${p.como}</small></span></div>
 <h4>Quem está retirando</h4><div class="row" style="margin-bottom:8px">${[['paciente','O próprio paciente'],...p.terc.map((t,i)=>['t'+i,t[0]+' · '+t[1].split(' · ')[0]]),['outro','Outra pessoa (não autorizada)']].map(([k,t])=>`<button class="chip ${EN_QUEM===k?'on':''}" onclick="EN_QUEM='${k}';enRender()">${t}</button>`).join('')}</div>
 ${EN_QUEM==='outro'?`<div class="alert warn"><span>Pessoa fora da lista: peça a autorização agora (o paciente responde pelo WhatsApp ou SMS em 1 clique, ou registre a verbal com data e hora) e cadastre o nome. Resultado sensível só com autorização específica.</span><div class="row" style="margin-top:6px"><button class="btn sm sec" onclick="toast('Pedido de autorização enviado ao paciente por WhatsApp; a resposta libera a retirada')">Pedir autorização pelo WhatsApp</button><button class="btn sm ghost" onclick="toast('Autorização verbal registrada com data, hora e quem registrou')">Registrar verbal</button></div></div>`:''}
 ${EN_QUEM!=='paciente'?`<div class="formgrid"><div class="field"><label>Nome de quem retira <span class="req">*</span></label><input class="in" value="${EN_QUEM.startsWith('t')?esc(p.terc[+EN_QUEM.slice(1)][0]):''}" placeholder="Nome completo"></div><div class="field"><label>Documento apresentado <span class="req">*</span></label><input class="in" placeholder="RG ou CNH"></div><div class="field"><label>Foto de quem retira ${info('Abre a câmera do computador ou do celular; a foto fica no registro da entrega, nunca no laudo.')}</label><button class="btn sec" style="width:100%" onclick="toast('Câmera aberta; foto guardada no registro da entrega')">📷 Fotografar</button></div><div class="field"><label>Parentesco</label><input class="in" value="${EN_QUEM.startsWith('t')?esc(p.terc[+EN_QUEM.slice(1)][1].split(' · ')[0]):''}" placeholder="ex.: filha"></div></div>`:`<div class="formgrid"><div class="field"><label>Documento apresentado <span class="req">*</span></label><input class="in" placeholder="RG ou CNH"></div></div>`}
 <h4 style="margin-top:8px">Impressão ${info('Padrão da unidade: preto e branco. A colorida pode ser escolhida aqui, a cada entrega.')}</h4><div class="row"><button class="chip ${EN_VER==='pb'?'on':''}" onclick="EN_VER='pb';enRender()">Preto e branco (padrão)</button><button class="chip ${EN_VER==='cor'?'on':''}" onclick="EN_VER='cor';enRender()">Colorida</button><button class="chip ${EN_VER==='nao'?'on':''}" onclick="EN_VER='nao';enRender()">Sem imprimir</button></div>
 <h4 style="margin-top:8px">Enviar ou reenviar também ${info('WhatsApp, SMS ou e-mail. Mensagem nunca traz resultado: vai o link com senha ou, se o paciente autorizou, o PDF.')}</h4><div class="row" style="gap:6px"><button class="btn sm wa" onclick="enEnviar('${p.prot}','WhatsApp')"><span class="wa-ic"><i class="fa-brands fa-whatsapp"></i></span> WhatsApp</button><button class="btn sm sec" onclick="enEnviar('${p.prot}','SMS')">SMS</button><button class="btn sm sec" onclick="enEnviar('${p.prot}','E-mail')">E-mail</button></div>`:''}
 </div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" ${p?'':'disabled'} onclick="closeModal();retorno('ok','Entrega registrada','Laudo ${p?p.prot:''} em G (entregue)${p&&EN_VER!=='nao'?', impresso em '+(EN_VER==='cor'?'cores':'preto e branco'):''}. Quem retirou, documento${p&&EN_QUEM!=='paciente'?', foto':''} e hora ficam no registro.')">Registrar entrega</button></div>`,'wide');const i=$('#enQ');if(i&&q!==undefined){i.focus();i.setSelectionRange(999,999)}}
function enEnviar(prot,canal){const p=EN_PACS.find(x=>x.prot===prot)||EN_PACS[0];openModal(`${mh('Enviar laudo · '+p.prot)}<div class="mb"><p style="font-size:14px"><b>${esc(p.n)}</b> · ${p.sit}</p><div class="field"><label>Por onde</label><div class="row">${['WhatsApp','SMS','E-mail'].map(c=>`<label class="chip ${(canal||'WhatsApp')===c?'on':''}"><input type="radio" name="enC" hidden ${(canal||'WhatsApp')===c?'checked':''}>${c}</label>`).join('')}</div></div><div class="field"><label>O que vai na mensagem</label><label class="check"><input type="radio" name="enO" checked>Link para abrir com senha (padrão)</label><label class="check"><input type="radio" name="enO" ${p.pdf?'':'disabled'}>PDF do laudo ${p.pdf?'':'<small class="tl">· o paciente não autorizou PDF por mensagem</small>'}</label></div><div class="field"><label>Para quem</label><select class="in"><option>O próprio paciente · ${p.canais.split(' ·')[0]} do cadastro</option>${p.terc.map(t=>`<option>${t[0]} (${t[1].split(' · ')[0]}) · autorizado</option>`).join('')}<option>Outro número ou e-mail (registra quem pediu)</option></select></div>${p.sens?'<div class="alert err"><span>Resultado sensível: só link com senha, nunca PDF.</span></div>':''}</div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();toast('Enviado por ${canal||'WhatsApp'}: link com senha; fica no histórico de entregas')">Enviar</button></div>`)}
GUIDES.entrega=['A lista mostra cada envio, por canal, com lido e baixado; filtre por período, unidade, canal e situação; falhas têm botão para corrigir e reenviar.','Na entrega no balcão, busque o paciente por CPF ou nome (a data de nascimento aparece ao lado), confira o que ele autorizou no atendimento, escolha quem retira (paciente ou terceiro nomeado, com documento e foto) e a versão de impressão.','Dali também se envia ou reenvia por WhatsApp, SMS ou e-mail: link com senha ou, se autorizado, PDF.'];
