function apHistDe(c){const conf=CONF.find(x=>x.prot==='10-00018233'&&x.ex===c);const h=conf?conf.hist:(LD_HIST[c]||[]);return h.length?h:(LE_DADOS['Maria Helena Souza']||{})[c]?LE_DADOS['Maria Helena Souza'][c].slice(1).map(([d,v])=>[d.slice(0,5),v]):[]}
