function apHistExames(){const l=['GLI','COL','TGO','HBA1C','HEMO','CREA','K'].filter(c=>apHistDe(c).length);if(!l.includes(AP_GRAF))AP_GRAF=l[0]||'GLI';return l}
function apAnterior(i){const a=AP_ANT[i];openDrawer('Atendimento de '+a.d,`${kvs([['Protocolo',`<span class="mono">${a.prot}</span>`],['Exames',a.ex.length],['Situação','<span class="badge ok">Pronto · laudo assinado</span>'],['Entregue por','WhatsApp (link com senha) · lido']])}<h4 style="margin-top:10px">Exames</h4><div class="at-list">${a.ex.map(c=>{const h=apHistDe(c);const f=FAIXA[c==='HEMO'?'HB':c];const v=h.length?h[0][1]:'—';const fora=f&&h.length&&(numRes(v)<f[0]||numRes(v)>f[1]);return `<div class="at-row clk" onclick="closeDrawer();apExame('${c}')"><div class="grow">${EX[c]?EX[c].n:c}<small>${f?'referência '+String(f[0]).replace('.',',')+' a '+String(f[1]).replace('.',',')+' '+f[2]:''}</small></div><b class="${fora?'fora':''}">${v}</b>${f?setaHtml(dirFaixa(numRes(v),f[0],f[1])):''}</div>`}).join('')}</div><div class="row" style="margin-top:12px;gap:6px"><button class="btn" onclick="toast('Laudo de ${a.d} aberto (preto e branco para baixar)')">Abrir laudo</button><button class="btn sec" onclick="closeDrawer();apEncaminhar()">Encaminhar</button></div>`)}
let AP_ENC={};
function apEncaminhar(c){AP_ENC={};if(c)AP_ENC[c]=true;apEncRender()}
