function tsGuia(id){const g=TS_GUIAS.find(x=>x.g===id)||TS_GUIAS[0];openDrawer('Guia '+g.g,`${kvs([['Beneficiário',`<b>${g.n}</b>`],['Carteirinha',`<span class="mono">${g.c}</span> · validade ${g.r.includes('carteirinha')?'<span class="prazo-err">vencida 09/2026</span>':'12/2027'}`],['Convênio','Unimed Fortaleza · TISS 4.01.00'],['Solicitante','Dr. Paulo Andrade · CRM-CE 11223'],['Atendimento','<span class="mono">10-000182'+g.g.slice(-2)+'</span> · 29/10 07:12'],['Autorização',g.r.includes('autoriza')?'<span class="badge warn">TSH sem número</span>':'<span class="mono">A7F2-9910</span>'],['Pedido digitalizado',g.r.includes('pedido')?'<span class="badge warn">ausente</span>':'<span class="badge ok">anexado</span>'],['Valor',g.v+' pela tabela vigente']])}<h4 style="margin-top:10px">Exames da guia</h4>${tabela(['TUSS','Exame','Valor'],[['40302040','Hemograma completo','R$ 20,50'],['40301630','Glicose','R$ 9,84'],['40316530','TSH','R$ 28,70'],['40301710','Colesterol total','R$ 24,60']].slice(0,+g.e).map(([t,n,v])=>`<tr>${td('TUSS',`<span class="mono">${t}</span>`)}${td('Exame',n)}${td('Valor',v)}</tr>`))}${g.r?`<div class="alert warn" style="margin-top:10px"><span><b>Risco de glosa:</b> ${g.r}. Resolva, retenha ou siga com registro antes de fechar o lote.</span></div>`:''}<div class="row" style="margin-top:12px;gap:6px">${g.r?`<button class="btn" onclick="toast('Risco resolvido e registrado')">Resolver</button><button class="btn sec" onclick="toast('Guia retida fora do lote','warn')">Reter</button>`:''}<button class="btn ghost" onclick="toast('Guia em PDF (modelo ANS) aberta')">Imprimir guia</button><button class="btn ghost" onclick="closeDrawer();location.hash='#atendimentos'">Abrir atendimento</button></div>`)}
/* 30/10 (anotação 120): lotes e glosas abrem detalhes ao clicar na linha */
function tsLote(l,c,p,g,v,s,pr){openDrawer('Lote '+l,`${kvs([['Convênio',c],['Período',p],['Guias',g],['Valor',v],['Situação',s],['Protocolo da operadora',pr==='—'?'<span class="tl">ainda não enviado</span>':`<span class="mono">${pr}</span>`],['Versão TISS','4.01.00'],['XML',s==='Aberto'?'gerado ao fechar':'validado contra o esquema da ANS']])}<h4 style="margin-top:10px">Linha do tempo</h4><div class="at-list">${[['Lote aberto','01/'+(p.startsWith('set')?'09':'10')+' · automático'],s!=='Aberto'?['Fechado e XML gerado','01/'+(p.startsWith('set')?'10':'11')+' · faturista']:null,pr!=='—'?['Protocolo recebido da operadora','03/10 · '+pr]:null,s==='Conciliado'?['Pagamento conciliado · glosa R$ 56,70','15/10 · OFX']:null,s==='Encerrado'?['Recursos encerrados','20/10']:null].filter(Boolean).map(([a,q])=>`<div class="at-row"><div class="grow">${a}<small>${q}</small></div></div>`).join('')}</div><div class="row" style="margin-top:12px;gap:6px">${s==='Aberto'?`<button class="btn" onclick="closeDrawer();tsFecharLote()">Fechar lote</button>`:`<button class="btn sec" onclick="toast('XML do lote baixado')">Baixar XML</button>`}<button class="btn ghost" onclick="TS_ABA='fila';closeDrawer();reView()">Ver guias</button></div>`)}
function tsGlosa(g,c,i,m,v,p,s){openDrawer('Glosa · '+g,`${kvs([['Convênio',c],['Item',i],['Motivo (ANS)',m],['Valor',v],['Prazo do recurso',p==='vencido'?'<span class="prazo-err">vencido</span>':p],['Situação',`<span class="badge ${s==='Revertida'?'ok':s==='Glosada'?'err':s==='Perda aceita'?'neutral':'warn'}">${s}</span>`],['Guia',`<span class="mono">${g}</span> · paciente e pedido digitalizado anexos`]])}<h4 style="margin-top:10px">Documentos</h4><div class="at-list">${['Guia SP/SADT assinada.pdf','Pedido médico.jpg',s!=='Glosada'?'Recurso enviado.pdf':null].filter(Boolean).map(a=>`<div class="at-row clk" onclick="toast('${a} aberto')"><div class="grow">${a}<small>anexo da guia</small></div></div>`).join('')}</div><div class="row" style="margin-top:12px;gap:6px">${s==='Glosada'?`<button class="btn" onclick="toast('Recurso enviado com a autorização anexada; prazo registrado')">Recorrer</button>`:''}<button class="btn ghost" onclick="toast('Histórico da glosa exportado')">Exportar</button></div>`)}
function tsFecharLote(){openModal(`${mh('Fechar lote UNI-2026-10')}<div class="mb"><div class="alert warn"><span><b>9 guias com risco de glosa.</b> O fechamento fica bloqueado até você resolver, reter ou seguir com registro em cada uma (CA03).</span></div><div class="mini">${miniKpi('Guias','118','')}${miniKpi('Resolvidas','4','')}${miniKpi('Retidas','2','ficam fora')}${miniKpi('Seguem com registro','3','','warn')}</div><p class="tl">O XML é validado contra o esquema da ANS antes de fechar; o lote guarda a versão TISS usada (4.01.00).</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Lote fechado','XML validado e gerado: 116 guias, R$ 40.410. Registre o envio e o protocolo quando subir no portal da Unimed.')">Validar e fechar</button></div>`)}
GUIDES.tiss=['Na fila, resolva ou retenha cada guia com risco antes de fechar o lote.','Feche o lote por convênio e período: o XML é validado e a versão TISS fica guardada; registre o envio e o protocolo.','Importe o demonstrativo para conciliar guia a guia; glosas ganham motivo e recurso com prazo.'];
REGRAS['Convênios e TISS']={aba:'Faturamento TISS',itens:[['RN01','Ao concluir atendimento de convênio gera guia SP/SADT com beneficiário, carteirinha, solicitante, exames (TUSS ou operadora), valor da tabela na data, autorização e token.'],['RN04','Pré-faturamento: seis pontos de risco por guia; o faturista resolve, retém ou segue com registro antes de fechar.'],['RN05','Lote por convênio e período; XML validado contra o esquema da ANS; envio registrado com protocolo; guia só sai de lote fechado com estorno do lote inteiro.'],['RN06/RN07','Conciliação do demonstrativo guia a guia; glosa item a item com motivo da ANS; recurso com justificativa, anexos e prazo; revertida ou perda aceita.'],['RN03','Exame que exige autorização sem número = risco de glosa; por convênio, aviso ou bloqueio no atendimento.'],['RN13','DeoClinic mantém a versão TISS vigente; cada lote guarda a versão usada.']]};

