function psItem(u,i){const [a,c,r,cv,o]=PS_DEMO[u][i];const k=typeof precoDe==='function'?precoDe(c,'custo'):EX[c].k;openDrawer('Atendimento '+a,`${kvs([['Exame',`<b>${EX[c]?EX[c].n:c}</b> · <span class="mono">${c}</span>`],['Repasse ao central',r],['Custo do exame',fmt(k)+' (cadastro do exame)'],['Lucro',/não entra/.test(o)?'não entra no repasse':r.startsWith('−')?r:fmt(psNum(r)-k)],['Convênio',cv],['Observação',o||'—'],['Paciente','ver no atendimento'],['Data','out/2026']])}<div class="row" style="margin-top:12px;gap:6px"><button class="btn sec" onclick="closeDrawer();location.hash='#atendimentos'">Abrir atendimento</button><button class="btn ghost" onclick="closeDrawer();exameMargem('${c}')">Tabelas deste exame</button></div>`)}
function psFechar(u){const x=PS_LISTA.find(p=>p.p.startsWith('Posto '+u)&&p.s==='Aberto')||PS_LISTA.find(p=>p.p.startsWith('Posto '+u));const i=PS_LISTA.indexOf(x);openModal(`${mh('Período fechado')}<div class="mb"><div class="at-found" style="flex-direction:row;gap:14px;align-items:center">${FIG('ok','fig-sm')}<div><h4 style="margin:0">${x.p} · ${x.pe}</h4><p style="margin:4px 0 0;font-size:14px">Demonstrativo gerado: ${x.a} atendimentos, repasse ${x.r}. O posto confere e aceita ou contesta item a item; aceito, a fatura vence em 5 dias.</p></div></div>${kvs([['Fatura',`<span class="mono">FAT-${u}-2026-10${x.pe.startsWith('16')?'B':'A'}</span>`],['Vencimento','5 dias após o aceite'],['Aviso','gestor do posto avisado pela Home e pelo WhatsApp']])}</div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn sec" onclick="psFatura(${i})" ${tipAttr('PDF da fatura','Abre a fatura do período como vai para o posto, com os itens, o total, o vencimento e os dados de pagamento.')}>${I.doc} Ver PDF da fatura</button><button class="btn" onclick="closeModal();toast('Demonstrativo e fatura enviados ao gestor do posto')">Enviar ao posto</button></div>`)}
function psFatura(i){const x=PS_LISTA[i]||PS_LISTA[0];const u=x.p.startsWith('Posto 14')?14:12;const demo=PS_DEMO[u];const alvo=parseFloat(x.r.replace(/\D/g,''))+318;const base=[['HEMO',421,14],['GLI',312,6],['COL',201,16],['TSH',118,13],['EAS',96,8],['HBA1C',72,9],['VITD',23,32],['PSA',19,26]];const k=alvo/base.reduce((s,[,q,v])=>s+q*v,0);const itens=base.map(([c,q,v])=>[c,Math.round(q*k),v]);const tot=itens.reduce((s,[,q,v])=>s+q*v,0);
 openModal(`${mh('Fatura · '+x.p+' · '+x.pe)}<div class="mb"><div class="laudo-prev pb" style="max-height:60vh"><div class="lp-top"><div><img src="logo-light.png" alt="DeoClinic"><div class="lp-lab">DeoClinic · Laboratório Central · CNPJ 00.000.000/0001-00<br>Rua das Flores, 120 · Fortaleza-CE · financeiro@deoclinic.com.br · (85) 3000-0000</div></div><div style="text-align:right;font-size:12px"><b style="font-size:15px;color:#111">FATURA DE REPASSE</b><br>Nº <b>FAT-${u}-2026-10${x.pe.startsWith('16')?'B':'A'}</b><br>Emitida em 31/10/2026</div></div>
 <div class="lp-pac"><span>Sacado<br><b>${x.p}</b></span><span>CNPJ<br><b>00.000.000/000${u}-00</b></span><span>Período<br><b>${x.pe}</b></span><span>Atendimentos<br><b>${x.a}</b></span><span>Vencimento<br><b>${x.s==='Pago'?'pago em 05/10':x.s==='Aberto'?'5 dias após o aceite':'10/11/2026'}</b></span><span>Situação<br><b>${x.s}</b></span></div>
 <h5>Itens por exame</h5><table><thead><tr><th>Exame</th><th>Quantidade</th><th>Valor de tabela</th><th style="text-align:right">Total</th></tr></thead><tbody>${itens.map(([c,q,v])=>`<tr><td><b>${EX[c]?EX[c].n:c}</b> <span style="color:#777">${c}</span></td><td>${q}</td><td>${fmt(v)}</td><td style="text-align:right">${fmt(q*v)}</td></tr>`).join('')}<tr><td colspan="3"><b>Cancelados, estornos e recoletas sem custo</b></td><td style="text-align:right;color:#C62828">− ${fmt(318)}</td></tr><tr><td colspan="3"><b>Convênios faturados pelo central (não entram)</b></td><td style="text-align:right;color:#777">R$ 6.410,00 · informativo</td></tr><tr style="background:#f4f7f6"><td colspan="3"><b style="font-size:14px">TOTAL A PAGAR</b></td><td style="text-align:right"><b style="font-size:15px">${fmt(tot-318)}</b></td></tr></tbody></table>
 <h5>Pagamento</h5><p style="font-size:12px;margin:0">Pix: <b>financeiro@deoclinic.com.br</b> (CNPJ) · Banco 000 · Agência 0001 · Conta 12345-6 · DeoClinic Laboratório Ltda.<br>Referência no pagamento: <b>FAT-${u}-2026-10${x.pe.startsWith('16')?'B':'A'}</b>. Contestações só pelo sistema, item a item, antes do aceite.</p>
 <div class="lp-rod"><div>Demonstrativo completo (${demo.length>4?x.a:demo.length} atendimentos, item a item) disponível no DeoClinic › Acerto entre postos.<br>Nota fiscal de serviço emitida fora do DeoClinic, com este número de fatura.</div><div style="text-align:right">${lpQr('FAT-'+u+'-'+x.pe)}</div></div></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn sec" onclick="toast('PDF da fatura aberto em nova aba')">Abrir PDF</button><button class="btn sec" onclick="toast('Fatura enviada à impressora')">${I.print} Imprimir</button><button class="btn" onclick="closeModal();toast('Fatura enviada ao gestor do posto por e-mail e WhatsApp')">Enviar ao posto</button></div>`,'wide')}
