function psDetalhe(i){const x=PS_LISTA[i];openDrawer(x.p+' · '+x.pe,`${kvs([['Situação',`<span class="badge neutral">${x.s}</span>`],['Atendimentos',x.a],['Repasse ao central',`<b>${x.r}</b>`],['Recebido no balcão do posto','R$ '+(Math.round(parseFloat(x.r.replace(/\D/g,''))*1.9/100)*100).toLocaleString('pt-BR')+' (valor ao cliente final)'],['Margem do posto','≈ 47% sobre o repasse'],['Convênios faturados pelo central','R$ 6.410 (fora do repasse)'],['Cancelados e estornos','− R$ 318'],['Contestações',x.c],['Vencimento',x.s==='Pago'?'pago em 05/10':'5 dias após o aceite']])}<h4 style="margin-top:10px">Repasse por exame (10 maiores)</h4><div class="barras">${[['Hemograma',16856],['Glicose',4812],['Colesterol',6720],['TSH',2990],['Urina tipo 1',2240]].map(([n,v])=>barra(n,v,16856,fmt(v))).join('')}</div><div class="row" style="margin-top:12px;gap:6px"><button class="btn sec" onclick="closeDrawer();psFatura(${i})" ${tipAttr('PDF da fatura','A fatura do período como vai para o posto: itens por exame, total, vencimento e dados de pagamento.')}>Ver PDF da fatura</button><button class="btn ghost" onclick="toast('Demonstrativo exportado em planilha e PDF')">Exportar demonstrativo</button>${x.x==='c'?`<button class="btn" onclick="closeDrawer();psContest()">Responder contestação</button>`:''}${x.x==='f'?`<button class="btn" onclick="closeDrawer();psFechar(${x.p.startsWith('Posto 14')?14:12})">Fechar período</button>`:''}</div>`)}
function psContest(){openModal(`${mh('Contestação · Posto 12 · outubro')}<div class="mb"><div class="at-list"><div class="at-row"><div class="grow">12-00002211 · Vitamina D · R$ 42,00<small>Posto: "exame foi faturado pelo posto, não pelo central". Justificativa anexada.</small></div></div></div><div class="field"><label>Resposta do central</label><select class="in"><option>Ajustado (entra como particular, R$ 42,00)</option><option>Resolvido (sem mudança de valor)</option><option>Mantido (com justificativa)</option></select></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();toast('Contestação respondida; o posto pode aceitar o demonstrativo')">Responder</button></div>`)}
