function fnPagarMotivo(c){const p=fnPapelDe(FN_USU);const a=alInfo(c);if(p==='gestor')return 'Gestor aprova, não paga: o pagamento é do financeiro.';if(a.rej)return 'Reprovada por '+a.rej.q+': precisa ser corrigida e reenviada.';if(!a.ok)return 'Falta aprovação: '+AL_ETAPA[a.prox]+' ('+alQuem(a.prox,c).join(' ou ')+').';return 'Quem lança não paga: '+(c.por||'Jânio')+' lançou esta conta. Outra pessoa do financeiro paga (ou o Administrador).'}
