 if(!ok&&pode)return `<button class="btn ${sm?'sm':''}" style="${sm?'margin-top:4px':''}" onclick="event.stopPropagation();alAprovar(${i})" ${tipAttr('Aprovar','Sua vez: '+AL_ETAPA[a.prox]+'. '+alFaixa(c)+' no centro '+a.cc+'.')}>Aprovar</button>`;
