function fnPagar(i){const c=CONTAS[i];if(!fnPodePagar(c)){toast(fnPagarMotivo(c),'warn');return}c.s='Paga';c.pagoPor=FN_USU;alAud(`${c.q} (${fmt(c.v)}) paga por ${FN_USU} · assinaturas: ${(c.ap||[]).map(x=>x.q).join(' + ')}`);closeDrawer();reView();toast('Pagamento de '+c.q+' registrado por '+FN_USU+'; conciliado pelo OFX quando o banco confirmar')}
