/* Orçamento por categoria: recorrentes fixas entram sozinhas; variáveis com estimativa editável */
let ORC_VISTA='mes';const ORC_EST={'1.1':110000,'1.2':125000,'1.3':95000,'1.4':30000,'1.5':5000,'2.1':31000,'2.2':2000,'2.3':1500,'3.1':58000,'3.2':47000,'3.3':10000,'4.3':9000,'4.6':1600,'4.8':2500,'4.9':2400};
function fnPrevisto(cod){const p=PLANO.find(x=>x[0]===cod);if(!p||p[2]==='grupo')return 0;if(ORC_EST[cod]!=null)return ORC_EST[cod];const fixas=CONTAS.filter(c=>c.cat===cod&&c.fixo&&c.rec!=='unica').reduce((s,c)=>s+(c.rec==='anual'?c.v/12:c.rec==='quinzenal'?c.v*2:c.rec==='semanal'?c.v*4.33:c.v),0);if(fixas)return Math.round(fixas);return Math.round((DRE_VAL[cod]||0)*0.98/100)*100}
function fnOrcTab(){const ano=ORC_VISTA==='ano';const m=ano?12:1;let tp=0,tr=0;
 const rows=PLANO.map(p=>{if(p[2]==='grupo')return `<tr style="background:var(--surface2)">${td('Categoria',`<b>${p[1]}</b>`)}${td('Tipo','')}${td('Previsto','')}${td('Realizado','')}${td('Diferença','')}</tr>`;const fixa=CONTAS.some(c=>c.cat===p[0]&&c.fixo&&c.rec!=='unica');const prev=fnPrevisto(p[0])*m,real=(DRE_VAL[p[0]]||0)*m,dif=real-prev;const receita=p[2]==='rec';const bom=receita?dif>=0:dif<=0;tp+=prev*(receita?1:-1);tr+=real*(receita?1:-1);
  return `<tr class="clk" onclick="fnPlanoCat('${p[0]}')">${td('Categoria',`<span style="padding-left:18px">${p[0]} · ${p[1]}</span>`)}${td('Tipo',fixa?'<span class="badge acc" '+tipAttr('Recorrente fixa','Previsto preenchido sozinho com as contas recorrentes de valor fixo desta categoria.')+'>recorrente fixa</span>':'<span class="badge neutral" '+tipAttr('Variável','Estimativa editável: clique no valor previsto e digite.')+'>variável · estimativa</span>')}${td('Previsto',fixa?fmt(prev):`<input class="in" style="width:120px;height:30px;text-align:right" value="${prev.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}" onclick="event.stopPropagation()" onchange="ORC_EST['${p[0]}']=Math.round((parseFloat(this.value.replace(/\\./g,'').replace(',','.'))||0)/${m});reView()" aria-label="Previsto para ${p[1]}">`)}${td('Realizado',fmt(real))}${td('Diferença',`<span style="color:${bom?'var(--ok)':'var(--err)'};font-weight:700">${dif>=0?'+':'−'} ${fmt(Math.abs(dif))}</span>`)}</tr>`});
 return `<div class="card at-card"><div class="h3row" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px"><h3 style="margin:0">Orçamento ${ano?'anual (2026)':'de outubro'} ${info('Previsto × realizado por categoria do plano de contas. Contas recorrentes de valor fixo entram sozinhas; as variáveis usam a estimativa, que você edita no campo. Diferença verde é a favor do laboratório.')}</h3><div class="row" style="gap:4px">${chip('Mês',!ano,`ORC_VISTA='mes';reView()`)}${chip('Ano',ano,`ORC_VISTA='ano';reView()`)}<button class="btn sm sec" onclick="toast('Orçamento copiado para o próximo mês com as mesmas estimativas')">Copiar para o próximo mês</button></div></div>
 <div class="mini"><div class="m"><div class="lab">Resultado previsto</div><div class="num">${fmt(tp)}</div></div><div class="m ${tr>=tp?'ok':'warn'}"><div class="lab">Resultado realizado</div><div class="num">${fmt(tr)}</div><div class="hint">${tr>=tp?'acima':'abaixo'} do previsto em ${fmt(Math.abs(tr-tp))}</div></div></div>
 ${tabela(['Categoria','Tipo','Previsto','Realizado','Diferença'],rows)}<p class="tl" style="margin-top:8px">Receitas: diferença positiva é boa. Custos e despesas: diferença negativa é boa (gastou menos que o previsto).</p></div>`}
function fnParceiro(n,b,r){openDrawer(n,`${kvs([['Recebe no balcão',fmt(b)+' (valor ao cliente final)'],['Repassa ao central',fmt(r)+' (tabela de repasse)'],['Fica com o posto',b===r?'fatura direta':fmt(b-r)+' · '+Math.round((b-r)/b*100)+'%'],['Período','outubro · acerto quinzenal']])}<h4 style="margin-top:10px">Por exame (5 maiores)</h4>${tabela(['Exame','Balcão','Repasse','Fica'],[['Hemograma',25,14],['Glicose',12,6],['Colesterol',30,16],['TSH',35,13],['Urina tipo 1',15,8]].map(([e,pb,pr])=>`<tr class="clk" onclick="exameMargem('${{Hemograma:'HEMO',Glicose:'GLI',Colesterol:'COL',TSH:'TSH','Urina tipo 1':'EAS'}[e]}')">${td('Exame',e)}${td('Balcão',fmt(pb))}${td('Repasse',fmt(pr))}${td('Fica',`${fmt(pb-pr)} <span class="mg ${(pb-pr)/pb<.2?'baixa':'ok'}">${Math.round((pb-pr)/pb*100)}%</span>`)}</tr>`))}<p class="tl" style="margin-top:8px">Clique no exame para ajustar as tabelas (preço ao paciente do posto e repasse).</p>`)}
/* Lançar conta (30/10, anotações 107 e 116): fornecedor com busca e cadastro rápido, categoria do plano, recorrência com valor fixo ou variável, anexos */
const FORNECEDORES=[{n:'Pardini',cat:'3.2',t:'apoio'},{n:'DB Diagnósticos',cat:'3.2',t:'apoio'},{n:'Beckman Coulter',cat:'4.4',t:'aparelhos e reagentes'},{n:'Labtubos Distribuidora',cat:'3.3',t:'tubos e materiais'},{n:'Diagnóstica Reagentes',cat:'3.1',t:'reagentes'},{n:'Limpa Mais Serviços',cat:'4.7',t:'limpeza'},{n:'Enel Ceará',cat:'4.3',t:'energia'},{n:'Cagece',cat:'4.3',t:'água'},{n:'Imobiliária Costa Sul',cat:'4.2',t:'aluguel'},{n:'Contábil Nordeste',cat:'4.5',t:'contador'},{n:'Unimed Fortaleza',cat:'1.2',t:'convênio'},{n:'Hapvida',cat:'1.2',t:'convênio'},{n:'Mineradora Vale Verde',cat:'1.4',t:'empresa'}];
let LC={forn:'',anx:[],rec:'unica',fixo:'fixo'};
function fnLancar(i,voltando){const c=i!=null?CONTAS[i]:null;const anxAntes=voltando?LC.anx:null,fornAntes=voltando?LC.forn:null;LC={forn:fornAntes??(c?c.q:''),anx:anxAntes??(c?[...c.anx]:[]),rec:c?c.rec:'unica',fixo:c?(c.fixo?'fixo':'var'):'fixo',cat:c?c.cat:'',tipo:c?c.t:'pagar',editando:i};
 openModal(`${mh(c?'Editar conta · '+esc(c.q):'Lançar conta')}<div class="mb"><div class="formgrid"><div class="field"><label>Tipo</label><select class="in" id="lcTipo"><option value="pagar" ${LC.tipo==='pagar'?'selected':''}>A pagar</option><option value="receber" ${LC.tipo==='receber'?'selected':''}>A receber</option></select></div>
 <div class="field" style="position:relative"><label>Favorecido / devedor <span class="req">*</span> ${info('Digite para buscar um fornecedor, convênio, posto ou empresa já cadastrado; se não existir, cadastre na hora sem sair daqui.')}</label><div class="inwrap lc-forn">${LUPA}<input class="in" id="lcForn" placeholder="Digite o nome" value="${esc(LC.forn)}" autocomplete="off" oninput="lcSugere(this.value);lcFornIc()" onfocus="lcSugere(this.value)"><span class="lc-ic"><button type="button" class="ibtn plain sm" id="lcFornEd" aria-label="Editar fornecedor" title="Editar o fornecedor escolhido" onclick="lcEditForn()" style="${FORNECEDORES.some(x=>x.n===LC.forn)?'':'display:none'}">${I.edit}</button><button type="button" class="ibtn plain sm lc-mais" aria-label="Cadastrar novo fornecedor" title="Cadastrar novo fornecedor" onclick="lcNovoForn(document.getElementById('lcForn').value)">${I.plus}</button></span></div><div id="lcSug" class="lc-sug"></div></div>
 <div class="field"><label>Categoria (plano de contas)</label><select class="in" id="lcCat" onchange="lcOrcAlerta()">${PLANO.filter(p=>p[2]==='grupo').map(g=>`<optgroup label="${g[0]} · ${g[1]}">${PLANO.filter(p=>p[2]!=='grupo'&&p[0].startsWith(g[0]+'.')).map(p=>`<option value="${p[0]}" ${LC.cat===p[0]?'selected':''}>${p[0]} · ${p[1]}</option>`).join('')}</optgroup>`).join('')}</select></div>
 <div class="field"><label>Vencimento</label><input class="in" type="date" value="${c?'2026-11-'+(c.venc.slice(0,2)==='ho'?'30':c.venc.slice(0,2)):''}"></div><div class="field"><label>Valor</label><input class="in" id="lcVal" placeholder="R$ 0,00" value="${c?c.v.toFixed(2).replace('.',','):''}" oninput="lcOrcAlerta()"></div><div class="field"><label>Centro de custo</label><select class="in"><option>Matriz</option><option>Posto 14</option><option>Posto 12</option><option>Área técnica</option></select></div>
 <div class="field"><label>Recorrência ${info('Única ou recorrente. Recorrente gera as próximas contas sozinha e entra no orçamento e no fluxo de caixa.')}</label><select class="in" id="lcRec" onchange="LC.rec=this.value;document.getElementById('lcFixo').style.display=this.value==='unica'?'none':''">${Object.entries(REC_NOME).map(([k,v])=>`<option value="${k}" ${LC.rec===k?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div>
 <div class="field" id="lcFixo" style="${LC.rec==='unica'?'display:none':''}"><label>Valor da recorrência ${info('Fixo: o mesmo valor todo período (aluguel, folha). Variável: muda a cada período (energia, reagentes); o valor digitado vira a estimativa do orçamento.')}</label><div class="row" style="gap:6px">${[['fixo','Fixo'],['var','Variável (estimativa)']].map(([k,t])=>`<label class="chip ${LC.fixo===k?'on':''}" onclick="LC.fixo='${k}';this.parentElement.querySelectorAll('.chip').forEach(x=>x.classList.toggle('on',x===this))"><input type="radio" name="lcFixo" hidden ${LC.fixo===k?'checked':''}>${t}</label>`).join('')}</div></div>
 <div class="field"><label>Parcelas</label><input class="in" value="1"></div>
 <div class="field" style="grid-column:1/-1"><label for="lcBol">Código de barras do boleto ${info('Digite ou cole a linha digitável (47 ou 48 números) ou leia com o leitor de código de barras. Valor e vencimento do boleto são conferidos com os da conta.')}</label><input class="in mono" id="lcBol" inputmode="numeric" placeholder="00000.00000 00000.000000 00000.000000 0 00000000000000" value="${esc(c&&c.bol||'')}" oninput="this.value=lcBolMask(this.value)"></div>
 <div class="field"><label for="lcPix">Chave Pix ${info('CPF, CNPJ, e-mail, telefone ou chave aleatória. Vem do cadastro do fornecedor, se houver; pode trocar só nesta conta.')}</label><input class="in" id="lcPix" placeholder="CNPJ, e-mail, telefone ou chave aleatória" value="${esc(c&&c.pix||(FORNECEDORES.find(x=>x.n===LC.forn)||{}).pix||'')}"></div></div>
 <div id="lcOrc"></div>
 <h4 style="margin-top:12px">Anexos ${info('Contrato, NF, recibo ou boleto ficam guardados com a conta, aparecem no histórico e na auditoria e saem na exportação para o contador.')}</h4><div id="lcAnx"></div>
 </div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="lcSalvar(${i!=null?i:'null'})">${c?'Salvar':'Lançar'}</button></div>`);lcAnxRender();lcOrcAlerta()}
const lcBolMask=s=>{const d=soDig(s).slice(0,48);return d.length<=47?d.replace(/^(\d{5})(\d)/,'$1.$2').replace(/^(\d{5}\.\d{5})(\d)/,'$1 $2').replace(/^(.{11} \d{5})(\d)/,'$1.$2').replace(/^(.{11} \d{5}\.\d{6})(\d)/,'$1 $2').replace(/^(.{24} \d{5})(\d)/,'$1.$2').replace(/^(.{24} \d{5}\.\d{6})(\d)/,'$1 $2').replace(/^(.{37} \d)(\d)/,'$1 $2'):d};
function lcFornIc(){const b=document.getElementById('lcFornEd'),v=(document.getElementById('lcForn')||{}).value||'';if(b)b.style.display=FORNECEDORES.some(x=>x.n===v.trim())?'':'none'}
/* Ao lançar: faltando 10% ou menos para o orçado da categoria, avisa quanto falta; estourando, avisa quem lança e quem paga */
function lcOrcAlerta(){const b=document.getElementById('lcOrc');if(!b)return;const cat=(document.getElementById('lcCat')||{}).value;const k=(PLANO.find(p=>p[0]===cat)||[])[2];const tipo=(document.getElementById('lcTipo')||{}).value||'pagar';if(tipo!=='pagar'||(k!=='cus'&&k!=='des')){b.innerHTML='';return}
 const v=parseFloat(((document.getElementById('lcVal')||{}).value||'').replace(/\./g,'').replace(',','.'))||0;const ant=LC.editando!=null&&CONTAS[LC.editando].cat===cat?CONTAS[LC.editando].v:0;const o=fnPrevisto(cat),pv=fnPrevistoLanc(cat)-ant+v;LC.orcEstoura=pv>o;
 b.innerHTML=pv>o?`<div class="alert err" style="margin-top:10px"><span><b>Esta conta estoura o orçamento de ${planoNome(cat)} em ${fmt(pv-o)}.</b> Orçado ${fmt(o)} · previsto com esta conta ${fmt(pv)}. Ao lançar, o alerta vai para você (quem lança) e para quem paga.</span></div>`:pv>=o*.9?`<div class="alert warn" style="margin-top:10px"><span><b>Faltam ${fmt(o-pv)} para estourar o orçamento de ${planoNome(cat)}</b> (${Math.round(pv/o*100)}% usado com esta conta). ${info('Aviso a partir de 90% do orçado. Orçado e metas se editam na DRE ou na aba Orçamento.')}</span></div>`:`<p class="tl" style="margin-top:8px">Orçamento de ${planoNome(cat)}: ${fmt(pv)} de ${fmt(o)} (${o?Math.round(pv/o*100):0}%) com esta conta.</p>`}
function lcEditForn(){const n=((document.getElementById('lcForn')||{}).value||'').trim();const fo=FORNECEDORES.find(x=>x.n===n);if(!fo){toast('Escolha um fornecedor cadastrado para editar','warn');return}const volta=lcGuarda();
 openModal(`${mh('Editar fornecedor · '+esc(fo.n))}<div class="mb"><div class="formgrid"><div class="field"><label>Nome <span class="req">*</span></label><input class="in" id="nfNome" value="${esc(fo.n)}"></div><div class="field"><label>CNPJ</label><input class="in" id="nfCnpj" value="${esc(fo.cnpj||'')}" placeholder="00.000.000/0000-00"></div><div class="field"><label>Contato (WhatsApp ou e-mail)</label><input class="in" id="nfCont" value="${esc(fo.cont||'')}"></div><div class="field"><label>Chave Pix</label><input class="in" id="nfPix" value="${esc(fo.pix||'')}"></div><div class="field"><label>Categoria padrão</label><select class="in" id="nfCat">${PLANO.filter(p=>p[2]!=='grupo').map(p=>`<option value="${p[0]}" ${p[0]===fo.cat?'selected':''}>${p[0]} · ${p[1]}</option>`).join('')}</select></div></div><p class="tl">Mudanças valem para as próximas contas; as já lançadas guardam o nome da época. Fica registrado quem alterou.</p></div><div class="mf"><button class="btn ghost" onclick="lcVolta()">Cancelar</button><button class="btn" onclick="lcEditFornOk('${fo.n.replace(/'/g,'')}')">Salvar</button></div>`);LC.volta=volta}
function lcEditFornOk(antigo){const fo=FORNECEDORES.find(x=>x.n===antigo);const n=(document.getElementById('nfNome').value||'').trim();if(!n){toast('Digite o nome','warn');return}Object.assign(fo,{n,cnpj:document.getElementById('nfCnpj').value,cont:document.getElementById('nfCont').value,pix:document.getElementById('nfPix').value,cat:document.getElementById('nfCat').value});LC.forn=n;if(LC.volta)LC.volta.lcForn=n;lcVolta();toast('Fornecedor “'+n+'” atualizado')}
function lcSugere(q){const box=document.getElementById('lcSug');if(!box)return;const s=semAc(q||'');const l=FORNECEDORES.filter(f=>!s||semAc(f.n).includes(s)).slice(0,4);box.innerHTML=`${l.map(f=>`<span class="lc-sug-l"><button type="button" onclick="lcEscolhe('${f.n.replace(/'/g,'')}')"><b>${f.n}</b><small>${f.t} · ${planoNome(f.cat)}</small></button><button type="button" class="lc-sug-ed" aria-label="Editar ${esc(f.n)}" title="Editar fornecedor" onclick="document.getElementById('lcForn').value='${f.n.replace(/'/g,'')}';lcEditForn()">${I.edit}</button></span>`).join('')}<button type="button" class="novo" onclick="lcNovoForn('${esc(q||'').replace(/'/g,'')}')">${I.plus||'+'} Cadastrar novo fornecedor${s&&!l.length?' “'+esc(q)+'”':''}</button>`;box.classList.add('show')}
function lcEscolhe(n){const f=FORNECEDORES.find(x=>x.n===n);LC.forn=n;const i=document.getElementById('lcForn');if(i)i.value=n;const c=document.getElementById('lcCat');if(c&&f)c.value=f.cat;const px=document.getElementById('lcPix');if(px&&f&&f.pix&&!px.value)px.value=f.pix;const box=document.getElementById('lcSug');if(box)box.classList.remove('show');lcFornIc();lcOrcAlerta()}
document.addEventListener('pointerdown',e=>{const box=document.getElementById('lcSug');if(box&&box.classList.contains('show')&&!e.target.closest('#lcSug,#lcForn'))box.classList.remove('show')},true);
function lcNovoForn(nome){const volta=lcGuarda();openModal(`${mh('Cadastrar fornecedor')}<div class="mb"><p class="tl">Cadastro rápido; o resto (endereço, contrato, condições) pode ser completado depois em Cadastros. Ao salvar, a conta volta com ele selecionado.</p><div class="formgrid"><div class="field"><label>Nome <span class="req">*</span></label><input class="in" id="nfNome" value="${esc(nome)}"></div><div class="field"><label>CNPJ</label><input class="in" id="nfCnpj" placeholder="00.000.000/0000-00"></div><div class="field"><label>Contato (WhatsApp ou e-mail)</label><input class="in" id="nfCont"></div><div class="field"><label>Categoria padrão</label><select class="in" id="nfCat">${PLANO.filter(p=>p[2]==='cus'||p[2]==='des').map(p=>`<option value="${p[0]}" ${p[0]==='4.9'?'selected':''}>${p[0]} · ${p[1]}</option>`).join('')}</select></div></div></div><div class="mf"><button class="btn ghost" onclick="lcVolta()">Cancelar</button><button class="btn" onclick="lcNovoFornOk()">Salvar e usar</button></div>`);LC.volta=volta;setTimeout(()=>document.getElementById('nfNome')?.focus(),50)}
function lcGuarda(){const g={};['lcTipo','lcForn','lcCat','lcVal','lcRec','lcBol','lcPix'].forEach(id=>{const e=document.getElementById(id);if(e)g[id]=e.value});return g}
function lcVolta(){const g=LC.volta||{};fnLancar(LC.editando,true);Object.entries(g).forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.value=v});if(LC.forn){const i=document.getElementById('lcForn');if(i)i.value=LC.forn}lcFornIc();lcOrcAlerta()}
function lcNovoFornOk(){const n=(document.getElementById('nfNome').value||'').trim();if(!n){toast('Digite o nome do fornecedor','warn');return}const cat=document.getElementById('nfCat').value;FORNECEDORES.unshift({n,cat,t:'novo'});LC.forn=n;lcVolta();const c=document.getElementById('lcCat');if(c)c.value=cat;toast('Fornecedor “'+n+'” cadastrado e selecionado')}
const LC_AMOSTRAS=[['Contrato 2026.pdf','PDF · 1,2 MB'],['NF 8812.pdf','PDF · 240 KB'],['Recibo out-2026.jpg','imagem · 410 KB'],['Boleto nov-2026.pdf','PDF · 96 KB']];
function lcAnexa(){const k=LC.anx.length%LC_AMOSTRAS.length;LC.anx.push(LC_AMOSTRAS[k][0]);lcAnxRender();toast('Arquivo anexado (no protótipo, um exemplo; no sistema, abre o seletor de arquivos ou a câmera)')}
function lcAnxRender(){const b=document.getElementById('lcAnx');if(!b)return;b.innerHTML=`${LC.anx.length?`<div class="at-list" style="margin-bottom:8px">${LC.anx.map((a,i)=>{const s=(LC_AMOSTRAS.find(x=>x[0]===a)||[a,'arquivo'])[1];return `<div class="at-row"><div class="grow">${a}<small>${s}</small></div><button class="btn sm ghost" onclick="LC.anx.splice(${i},1);lcAnxRender()">Remover</button></div>`}).join('')}</div>`:'<p class="tl" style="margin-bottom:8px">Nenhum anexo ainda.</p>'}<button type="button" class="btn sm sec" onclick="lcAnexa()">${I.plus||'+'} Anexar arquivo</button> <span class="tl">PDF, imagem ou XML · até 20 MB cada</span>`}
function lcSalvar(i){const forn=(document.getElementById('lcForn')?.value||'').trim();if(!forn){toast('Informe o favorecido ou devedor','warn');document.getElementById('lcForn')?.focus();return}const v=parseFloat((document.getElementById('lcVal')?.value||'').replace(/\./g,'').replace(',','.'))||0;const cat=document.getElementById('lcCat')?.value||'4.9';const t=document.getElementById('lcTipo')?.value||'pagar';
 const bol=document.getElementById('lcBol')?.value||'',pix=(document.getElementById('lcPix')?.value||'').trim();if(bol&&![47,48].includes(soDig(bol).length)){toast('Código de barras incompleto: são 47 números (boleto) ou 48 (conta de consumo)','warn');document.getElementById('lcBol').focus();return}const estoura=LC.orcEstoura;
 if(i!=null){if(v&&v!==CONTAS[i].v&&(CONTAS[i].ap||[]).length){alAud(`${CONTAS[i].q}: valor alterado de ${fmt(CONTAS[i].v)} para ${fmt(v)}; assinaturas recomeçam`);CONTAS[i].ap=[];if(CONTAS[i].s==='Aprovada')CONTAS[i].s='A vencer'}Object.assign(CONTAS[i],{q:forn,cat,t,v:v||CONTAS[i].v,rec:LC.rec,fixo:LC.fixo==='fixo',anx:[...LC.anx],bol,pix})}else CONTAS.push({t,por:FN_USU,q:forn,tipo:(FORNECEDORES.find(f=>f.n===forn)||{}).t||'fornecedor',cat,ref:'lançamento manual',venc:'30/11',v,s:'A vencer',rec:LC.rec,fixo:LC.fixo==='fixo',anx:[...LC.anx],bol,pix,ap:[]});
 if(i==null&&t==='pagar')alAud(`${forn} (${fmt(v)}) lançada por ${FN_USU}; entra na alçada: ${alFaixa(CONTAS[CONTAS.length-1])}`);
 closeModal();FN_ABA=t;reView();if(estoura&&t==='pagar'){retorno('warn','Orçamento estourado: '+planoNome(cat),'Conta lançada. O alerta foi enviado para quem lançou ('+FN_USU+') e para quem paga ('+FN_USUS.filter(u=>u[0]!==FN_USU).map(u=>u[0]).join(' e ')+'). Ajuste o orçado na DRE, se for o caso.');return}toast((i!=null?'Conta atualizada':'Conta lançada')+(LC.rec!=='unica'?'; recorrência '+REC_NOME[LC.rec]+' ('+(LC.fixo==='fixo'?'valor fixo':'estimativa')+') entra no orçamento e no fluxo':'; aviso 3 dias antes do vencimento')+(LC.anx.length?' · '+LC.anx.length+' anexo(s)':''))}
document.head.insertAdjacentHTML('beforeend',`<style>.lc-sug{display:none;position:absolute;left:0;right:0;top:100%;z-index:5;background:var(--surface);border:1px solid var(--border);border-radius:12px;box-shadow:var(--shadow);padding:4px;max-height:240px;overflow:auto}.lc-sug.show{display:block}.lc-sug button{display:flex;flex-direction:column;align-items:flex-start;width:100%;text-align:left;border:0;background:transparent;color:var(--fg);padding:7px 10px;border-radius:8px;cursor:pointer;font:inherit}.lc-sug button:hover{background:var(--surface2)}.lc-sug button b{color:var(--fg-strong)}.lc-sug button small{color:var(--fg2);font-size:12px}.lc-sug button.novo{color:var(--accent);font-weight:700;border-top:1px solid var(--border);border-radius:0 0 8px 8px;flex-direction:row;gap:6px}
.laudo-prev{background:#fff;color:#222;border:1px solid var(--border);border-radius:8px;padding:22px 26px;font-size:13px;max-height:62vh;overflow:auto}.laudo-prev.pb{filter:grayscale(1)}.laudo-prev .lp-top{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;border-bottom:2px solid #2E7D6B;padding-bottom:10px;margin-bottom:10px}.laudo-prev .lp-top img{height:44px}.laudo-prev .lp-lab{font-size:11.5px;color:#555;line-height:1.4}.laudo-prev .lp-pac{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:4px 14px;font-size:12px;background:#f4f7f6;border-radius:8px;padding:8px 12px;margin-bottom:10px}.laudo-prev .lp-pac b{color:#111}.laudo-prev h5{margin:12px 0 4px;font-size:13px;color:#2E7D6B;text-transform:uppercase;letter-spacing:.04em}.laudo-prev table{width:100%;border-collapse:collapse;font-size:12.5px}.laudo-prev th,.laudo-prev td{text-align:left;padding:5px 6px;border-bottom:1px solid #e3e8e6;vertical-align:middle;color:#222}.laudo-prev th{font-size:11px;color:#666;text-transform:uppercase}.laudo-prev .lp-fora{color:#C62828;font-weight:800}.laudo-prev .regua{width:110px}.laudo-prev .lp-rod{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;border-top:1px solid #e3e8e6;margin-top:14px;padding-top:10px;font-size:11.5px;color:#555}.laudo-prev .lp-qr{width:64px;height:64px}.laudo-prev .lp-ass{font-family:cursive;font-size:18px;color:#1b4f44}.laudo-prev .lp-pg{font-size:10.5px;color:#888;text-align:right;margin-top:6px}
.lp-sel{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 10px}.lp-sel label{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--border);border-radius:999px;padding:4px 10px;font-size:13px;cursor:pointer;background:var(--surface)}.lp-sel label.on{border-color:var(--accent);background:var(--accent-soft)}</style>`);
GUIDES.financeiro=['A visão do mês traz faturamento bruto, custo, a receber e a pagar, com recepção, postos e empresas separados e juntos; todo número, fatia e barra abre o detalhe; filtre por período, unidade e lado.','O quadro Postos e parceiros mostra o que cada um recebe no balcão, o que repassa ao central e o que fica com ele, por exame.','A receber e a pagar listam vencimentos; baixa e conciliação pelo identificador do atendimento ou OFX.','A conciliação compara os fechamentos item a item com o extrato.','Aprovações: a fila mostra o que espera a sua assinatura, quem assina depois e o que foi reprovado (com motivo); use Testar como para ver cada pessoa.','Alçadas: faixas de valor por centro de custo (gestor; dupla assinatura com o diretor financeiro; Administrador acima do 2º limite) e teto por pessoa. Só o Administrador altera; fica na trilha.'];
REGRAS['Financeiro']={aba:'Blocos do catálogo (B8) e Atendimento (caixa)',itens:[['Escopo','Financeiro completo opcional (ou só caixa + exportação): a receber (convênios, postos, particular, empresas), a pagar (apoio, fornecedores, despesas) com vencimentos, parcelas, baixa e avisos.'],['Caixa','Conciliação bancária por OFX e de Pix/cartão pelo identificador do atendimento; fechamentos item a item com relatório para prestar contas.'],['Visão','Faturamento, custo e resultado por lado (B2C e B2B) e por unidade; DRE por unidade e consolidada; custo x preço com alerta abaixo do custo.'],['Contador','Acesso temporário a um módulo com data de fim, expira sozinho e fica registrado (B13).'],['Alçadas','Toda conta a pagar passa pela alçada do centro de custo: até o 1º limite (ex.: R$ 2.000 na Matriz) o gestor aprova; até o 2º (R$ 20.000) dupla assinatura gestor + diretor financeiro; acima, também o Administrador. Limites por centro de custo e teto por pessoa configuráveis só pelo Administrador.'],['Segregação','Quem lança não aprova nem paga (exceção do Administrador, marcada na trilha); as assinaturas são de pessoas diferentes; gestor aprova mas não paga; Pagar fica bloqueado até a última assinatura.'],['Reprovação','Reprovar pede motivo; a conta volta para quem lançou e o reenvio recomeça as assinaturas. Mudar o valor também recomeça.'],['Trilha','Assinatura, reprovação, reenvio, pagamento e mudança de alçada ficam na trilha de auditoria, com quem, quando e antes/depois (corrige o marcarautorizado sem permissão do Clinicas).']]};

